"""Changelog and version files from Conventional Commit messages. See task.md."""

from __future__ import annotations

import os
import re


class CommitError(ValueError):
    """Raised when `previous_version` is not a valid `X.Y.Z` version."""


_HEADER = re.compile(r"([a-z]+)(?:\(([^()]*)\))?(!)?:(.*)", re.DOTALL)
_VERSION = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)")
_BREAK_TOKENS = ("BREAKING CHANGE:", "BREAKING-CHANGE:")


def _parse(commit: str):
    subject, sep, body = commit.partition("\n\n")
    subject = subject.strip()
    if "\n" in subject or "\r" in subject:
        return None
    m = _HEADER.fullmatch(subject)
    if m is None:
        return None
    type_, scope, bang, desc = m.groups()
    desc = desc.strip()
    if not desc:
        return None
    scope = (scope or "").strip() or None
    breaking = bool(bang)
    if not breaking and sep:
        for line in re.split(r"\r\n|\r|\n", body):
            if line.strip().startswith(_BREAK_TOKENS):
                breaking = True
                break
    return type_, scope, desc, breaking


def build(commits: list[str], previous_version: str, out_dir: str) -> None:
    """Write `<out_dir>/CHANGELOG.md` and `<out_dir>/version.txt`."""
    m = _VERSION.fullmatch(previous_version)
    if m is None:
        raise CommitError(f"invalid version: {previous_version!r}")
    major, minor, patch = (int(g) for g in m.groups())

    sections = {"breaking": set(), "feat": set(), "fix": set(), "perf": set()}
    any_break = any_feat = any_fix = False
    for commit in commits:
        parsed = _parse(commit)
        if parsed is None:
            continue
        type_, scope, desc, breaking = parsed
        if breaking:
            any_break = True
            sections["breaking"].add((scope, desc))
        elif type_ in ("feat", "fix", "perf"):
            sections[type_].add((scope, desc))
        if type_ == "feat":
            any_feat = True
        elif type_ in ("fix", "perf"):
            any_fix = True

    if any_break:
        version = f"{major + 1}.0.0"
    elif any_feat:
        version = f"{major}.{minor + 1}.0"
    elif any_fix:
        version = f"{major}.{minor}.{patch + 1}"
    else:
        version = previous_version

    out = f"## {version}\n"
    titles = [
        ("breaking", "Breaking changes"),
        ("feat", "Features"),
        ("fix", "Fixes"),
        ("perf", "Performance"),
    ]
    for key, title in titles:
        entries = sections[key]
        if not entries:
            continue
        out += f"\n### {title}\n\n"
        for scope, desc in sorted(entries, key=lambda e: (e[0] is None, e[0] or "", e[1])):
            out += f"- **{scope}**: {desc}\n" if scope else f"- {desc}\n"

    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "CHANGELOG.md"), "w", encoding="utf-8", newline="") as f:
        f.write(out)
    with open(os.path.join(out_dir, "version.txt"), "w", encoding="utf-8", newline="") as f:
        f.write(version + "\n")
